<?php
declare(strict_types=1);namespace App\Controllers;
use App\Core\Database;use App\Core\Request;
final class ReportController extends BaseController {
 public function index(Request $r):void{$this->auth();$this->require('reports.view');$pdo=Database::connection();$data=['requests'=>(int)$pdo->query('SELECT COUNT(*) FROM purchase_requests')->fetchColumn(),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM purchase_orders')->fetchColumn(),'vendors'=>(int)$pdo->query('SELECT COUNT(*) FROM vendors')->fetchColumn(),'spend'=>$pdo->query("SELECT currency_code,SUM(total_amount) total FROM purchase_orders GROUP BY currency_code")->fetchAll(),'statuses'=>$pdo->query('SELECT status,COUNT(*) total FROM purchase_orders GROUP BY status')->fetchAll()];$this->view('reports/index',['data'=>$data]);}
 public function export(Request $r):void{$this->auth();$this->require('reports.export');$type=(string)$r->input('type','purchase_orders');$map=['purchase_orders'=>'SELECT po_number,vendor_id,ship_to_branch_id,currency_code,order_date,total_amount,status,created_at FROM purchase_orders','purchase_requests'=>'SELECT request_no,requester_user_id,branch_id,department_id,currency_code,required_by,status,created_at FROM purchase_requests','vendors'=>'SELECT vendor_code,legal_name,tax_registration_no,website,status,created_at FROM vendors','invoices'=>'SELECT invoice_no,vendor_id,purchase_order_id,currency_code,invoice_date,due_date,total_amount,status FROM invoices','payments'=>'SELECT payment_reference,vendor_id,currency_code,payment_date,payment_method,amount,status FROM payments'];if(!isset($map[$type])){http_response_code(400);exit('Invalid export type');}$rows=Database::connection()->query($map[$type])->fetchAll();$format=(string)$r->input('format','csv');if($format==='xlsx'){if(!class_exists(\PhpOffice\PhpSpreadsheet\Spreadsheet::class)){http_response_code(500);exit('Install Composer dependencies first.');}$book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();if($rows){$sheet->fromArray(array_keys($rows[0]),null,'A1');$sheet->fromArray(array_map('array_values',$rows),null,'A2');}$writer=new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$type.'.xlsx"');$writer->save('php://output');exit;}if($format==='pdf'){if(!class_exists(\Dompdf\Dompdf::class)){http_response_code(500);exit('Install Composer dependencies first.');}$html='<h2>NSG Procurement - '.htmlspecialchars(ucwords(str_replace('_',' ',$type))).'</h2><table border="1" cellpadding="5"><tr>';foreach(array_keys($rows[0]??['No records'=>null]) as $h)$html.='<th>'.htmlspecialchars((string)$h).'</th>';$html.='</tr>';foreach($rows as $row){$html.='<tr>';foreach($row as $v)$html.='<td>'.htmlspecialchars((string)$v).'</td>';$html.='</tr>';}$html.='</table>';$pdf=new \Dompdf\Dompdf();$pdf->loadHtml($html);$pdf->setPaper('A4','landscape');$pdf->render();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$type.'.pdf"');echo $pdf->output();exit;}
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$type.'.csv"');$out=fopen('php://output','w');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $row)fputcsv($out,$row);}fclose($out);exit;}
}
